.darma-loader-darma-b17-lissajous-trace { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #a3e635); width: var(--loader-size, 116px); height: var(--loader-size, 116px); position: relative; }
.darma-loader-darma-b17-lissajous-trace .darma-loader-darma-b17-lissajous-trace__frame { position: absolute; inset: 0; border-radius: 8px; box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--accent) 28%, transparent); background: radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 72%); }
.darma-loader-darma-b17-lissajous-trace i { position: absolute; left: 46%; top: 46%; width: 8%; height: 8%; border-radius: 50%; background: var(--accent-2); box-shadow: 0 0 10px color-mix(in srgb, var(--accent-2) 70%, transparent); animation: darma-loader-darma-b17-lissajous-trace-liss-x calc(var(--loader-speed, 1s) * 2) ease-in-out infinite alternate, darma-loader-darma-b17-lissajous-trace-liss-y calc(var(--loader-speed, 1s) * 3) ease-in-out infinite alternate; }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(1) { opacity: 1; }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(2) { opacity: .68; animation-delay: calc(var(--loader-speed, 1s) * -.1), calc(var(--loader-speed, 1s) * -.1); }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(3) { opacity: .5; animation-delay: calc(var(--loader-speed, 1s) * -.2), calc(var(--loader-speed, 1s) * -.2); }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(4) { opacity: .36; animation-delay: calc(var(--loader-speed, 1s) * -.3), calc(var(--loader-speed, 1s) * -.3); }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(5) { opacity: .24; animation-delay: calc(var(--loader-speed, 1s) * -.4), calc(var(--loader-speed, 1s) * -.4); }
.darma-loader-darma-b17-lissajous-trace i:nth-of-type(6) { opacity: .14; animation-delay: calc(var(--loader-speed, 1s) * -.5), calc(var(--loader-speed, 1s) * -.5); }
@keyframes darma-loader-darma-b17-lissajous-trace-liss-x { from { left: 8%; } to { left: 84%; } }
@keyframes darma-loader-darma-b17-lissajous-trace-liss-y { from { top: 8%; } to { top: 84%; } }

